narrative:
## Collecting Successes and Failures

Sometimes you CAN'T use `?` because you want ALL operations to run, not stop at the first error. Instead, you collect each result and count successes vs failures.

### The Operations

Five independent checks, each returning `Result[Str, Str]`:

```xiom
fn check_not_empty(val: Str) -> Result[Str, Str] {
  if string.str_len(val) == 0 {
    return Err("Value is empty");
  }
  return Ok("NotEmpty: OK");
}

fn check_is_number(val: Str) -> Result[Str, Str] {
  match string.str_to_int(val) {
    Ok(_) => { return Ok("IsNumber: OK"); }
    Err(_) => { return Err("Not a number: '" + val + "'"); }
  }
}

fn check_positive(val: Str) -> Result[Str, Str] {
  let n = string.str_to_int(val);
  match n {
    Ok(num) => {
      if num > 0 { return Ok("Positive: OK"); }
      else { return Err("Not positive: " + string.int_to_str(num)); }
    }
    Err(_) => { return Err("Cannot check: not a number"); }
  }
}

fn check_length(val: Str) -> Result[Str, Str] {
  if string.str_len(val) < 3 {
    return Err("Too short: " + string.int_to_str(string.str_len(val)) + " chars");
  }
  return Ok("Length: OK");
}

fn check_no_spaces(val: Str) -> Result[Str, Str] {
  if string.str_contains(val, " ") {
    return Err("Contains spaces");
  }
  return Ok("NoSpaces: OK");
}
```

### Running All Checks

Use `match` on each result individually — never `?` — so every check executes:

```xiom
fn run_all_checks(val: Str) -> (Int, Int, Str) {
  let ok_count = 0;
  let fail_count = 0;
  let failures = "";

  match check_not_empty(val) {
    Ok(_) => { ok_count = ok_count + 1; }
    Err(e) => { fail_count = fail_count + 1; failures = failures + e + "; "; }
  }

  match check_is_number(val) {
    Ok(_) => { ok_count = ok_count + 1; }
    Err(e) => { fail_count = fail_count + 1; failures = failures + e + "; "; }
  }

  match check_positive(val) {
    Ok(_) => { ok_count = ok_count + 1; }
    Err(e) => { fail_count = fail_count + 1; failures = failures + e + "; "; }
  }

  match check_length(val) {
    Ok(_) => { ok_count = ok_count + 1; }
    Err(e) => { fail_count = fail_count + 1; failures = failures + e + "; "; }
  }

  match check_no_spaces(val) {
    Ok(_) => { ok_count = ok_count + 1; }
    Err(e) => { fail_count = fail_count + 1; failures = failures + e + "; "; }
  }

  return (ok_count, fail_count, failures);
}
```

### Printing the Summary

```xiom
fn main() -> Int {
  let (ok, fail, reasons) = run_all_checks("42");
  io.println(string.int_to_str(ok) + " passed, " + string.int_to_str(fail) + " failed");
  if fail > 0 {
    io.println("Reasons: " + reasons);
  }

  let (ok2, fail2, reasons2) = run_all_checks("");
  io.println(string.int_to_str(ok2) + " passed, " + string.int_to_str(fail2) + " failed");
  if fail2 > 0 {
    io.println("Reasons: " + reasons2);
  }

  return 0;
}
```

### When to Use This Pattern

- **Test suites**: Run all tests, report which passed and which failed
- **Batch validation**: Validate 100 records, collect all errors instead of stopping at the first
- **Health checks**: Check database, cache, API — report status of each individually

