solution:
use xiom.io;

use xiom.string;
fn check_a(val: Str) -> Result[Str, Str] {
  if string.str_len(val) == 0 {
    return Err("Value is empty");
  }
  return Ok("OK");
}

fn check_b(val: Str) -> Result[Str, Str] {
  match string.str_to_int(val) {
    Ok(_) => { return Ok("OK"); }
    Err(_) => { return Err("Not a number"); }
  }
}

fn run_all(val: Str) -> (Int, Int) {
  let ok = 0;
  let fail = 0;

  match check_a(val) {
    Ok(_) => { ok = ok + 1; }
    Err(_) => { fail = fail + 1; }
  }

  match check_b(val) {
    Ok(_) => { ok = ok + 1; }
    Err(_) => { fail = fail + 1; }
  }

  return (ok, fail);
}

fn main() -> Int {
  let (ok, fail) = run_all("hello");
  io.println(string.int_to_str(ok) + " passed, " + string.int_to_str(fail) + " failed");
  return 0;
}
